// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');
const loadMontserrat = makeLoadFont('Montserrat');

const { fontFamily: interFamily } = loadInter();
const { fontFamily: montserratFamily } = loadMontserrat();



export type CasinoOverlayProps = Record<string, any>;

// Helpers
const parseCard = (cardString: string) => {
  const suit = cardString.slice(-1);
  const value = cardString.slice(0, -1);
  const isRed = suit === "♥" || suit === "♦";
  return { value, suit, isRed };
};

const CardFace: React.FC<{ cardStr: string; accentGold: string }> = ({ cardStr, accentGold }) => {
  const { value, suit, isRed } = parseCard(cardStr);
  return (
    <div
      style={{
        width: 80,
        height: 112,
        backgroundColor: "#F9F9F9",
        borderRadius: 8,
        boxShadow: "0 6px 16px rgba(0,0,0,0.4)",
        position: "relative",
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        color: isRed ? "#E63946" : "#111111",
        fontFamily: interFamily,
        border: `1px solid ${accentGold}30`,
        boxSizing: "border-box",
      }}
    >
      <div style={{ position: "absolute", top: 4, left: 6, display: "flex", flexDirection: "column", alignItems: "center" }}>
        <div style={{ fontSize: 16, fontWeight: 900, lineHeight: 1 }}>{value}</div>
        <div style={{ fontSize: 12, lineHeight: 1 }}>{suit}</div>
      </div>
      <div style={{ fontSize: 36, opacity: 0.9 }}>{suit}</div>
      <div style={{ position: "absolute", bottom: 4, right: 6, display: "flex", flexDirection: "column", alignItems: "center", transform: "rotate(180deg)" }}>
        <div style={{ fontSize: 16, fontWeight: 900, lineHeight: 1 }}>{value}</div>
        <div style={{ fontSize: 12, lineHeight: 1 }}>{suit}</div>
      </div>
    </div>
  );
};

const CardBack: React.FC<{ accentGold: string }> = ({ accentGold }) => {
  return (
    <div
      style={{
        width: 80,
        height: 112,
        backgroundColor: "#111111",
        borderRadius: 8,
        border: "2px solid #EAEAEA",
        position: "relative",
        overflow: "hidden",
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        boxSizing: "border-box",
      }}
    >
      <svg width="100%" height="100%" style={{ position: "absolute", top: 0, left: 0 }}>
        <defs>
          <pattern id="card-pattern" width="12" height="12" patternUnits="userSpaceOnUse" patternTransform="rotate(45)">
            <rect width="2" height="12" fill={accentGold} fillOpacity="0.3" />
          </pattern>
        </defs>
        <rect width="100%" height="100%" fill="url(#card-pattern)" />
      </svg>
      <div style={{ width: 40, height: 64, backgroundColor: "#111", border: `2px solid ${accentGold}80`, zIndex: 1, borderRadius: 4 }} />
    </div>
  );
};

const CasinoOverlay: React.FC<CasinoOverlayProps> = ({
  backgroundColor = "#000000",
  transparentBackground = true,
  durationInSeconds = 10,
  playerName = "Malloy Studio",
  playerHand = ["A♠", "K♠"],
  dealerName = "DEALER",
  dealerHand = ["7♥", "2♣"],
  communityCards = ["Q♠", "J♠", "10♠", "4♦", "9♣"],
  betAnte = "$50",
  betBlind = "$50",
  betPlay = "$100",
  betTrips = "$25",
  highlightWinner = "Player",
  accentGold = "#D4AF37",
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Global Timeline
  const overlayEnter = spring({ frame, fps, config: { damping: 16 } });
  const baseOpacity = interpolate(overlayEnter, [0, 1], [0, 1]);
  // Re-map to slide in from the left rather than the bottom
  const baseTranslateX = interpolate(overlayEnter, [0, 1], [-40, 0]);

  const showWinnerProgress = spring({ frame: frame - 175, fps, config: { damping: 12 } });
  const playerWinIntensity = highlightWinner === "Player" ? interpolate(showWinnerProgress, [0, 1], [0, 1]) : 0;
  const dealerWinIntensity = highlightWinner === "Dealer" ? interpolate(showWinnerProgress, [0, 1], [0, 1]) : 0;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      <AbsoluteFill
        style={{
          opacity: baseOpacity,
          transform: `scale(0.75) translateX(${baseTranslateX}px)`,
          transformOrigin: "bottom left",
          transition: "none",
          display: "flex",
          flexDirection: "column",
          justifyContent: "flex-end", // Clustered at the bottom
          alignItems: "flex-start", // Tucked to the left side
          paddingBottom: "60px",
          paddingLeft: "60px",
          gap: "24px",
        }}
      >
        {/* DEALER ZONE */}
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            padding: "16px 32px",
            borderRadius: 16,
            backgroundColor: "rgba(18, 18, 20, 0.7)",
            backdropFilter: "blur(12px)",
            border: `1px solid rgba(255,255,255,${0.05 + dealerWinIntensity * 0.3})`,
            boxShadow: `0 8px 24px rgba(0,0,0,0.4), 0 0 ${dealerWinIntensity * 30}px ${accentGold}40`,
            transition: "none",
          }}
        >
          <span style={{ fontFamily: montserratFamily, color: "#FFFFFF", fontSize: 14, fontWeight: 700, letterSpacing: 4, marginBottom: 12, opacity: 0.8 }}>
            {dealerName.toUpperCase()}
          </span>
          <div style={{ display: "flex", gap: 10 }}>
            {dealerHand.map((card, idx) => {
              const flipStart = 140 + idx * 10;
              const flipProgress = spring({ frame: frame - flipStart, fps, config: { damping: 14 } });
              const scaleX = interpolate(flipProgress, [0, 0.5, 1], [1, 0, 1], { extrapolateRight: "clamp" });
              const isFlipped = flipProgress > 0.5;

              const enterProgress = spring({ frame: frame - 10 - idx * 5, fps, config: { damping: 14 } });
              const y = interpolate(enterProgress, [0, 1], [-20, 0]);
              const opacity = enterProgress;

              return (
                <div key={idx} style={{ transform: `translateY(${y}px) scaleX(${scaleX})`, opacity, transition: "none" }}>
                  {isFlipped ? <CardFace cardStr={card} accentGold={accentGold} /> : <CardBack accentGold={accentGold} />}
                </div>
              );
            })}
          </div>
        </div>

        {/* COMMUNITY BOARD */}
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
          }}
        >
          <span style={{ fontFamily: montserratFamily, color: accentGold, fontSize: 12, fontWeight: 700, letterSpacing: 6, marginBottom: 12, opacity: 0.9 }}>
            COMMUNITY BOARD
          </span>
          <div style={{ display: "flex", gap: 12, padding: "16px 32px", backgroundColor: "rgba(12, 12, 14, 0.8)", borderRadius: 16, border: `1px solid ${accentGold}20`, backdropFilter: "blur(16px)" }}>
            {communityCards.map((card, idx) => {
              // Flop (0,1,2) at f=45, Turn (3) at f=75, River (4) at f=105
              let delay = 45;
              if (idx === 3) delay = 75;
              if (idx === 4) delay = 105;
              if (idx < 3) delay += idx * 4; // Stagger flop slightly

              const enterProgress = spring({ frame: frame - delay, fps, config: { damping: 14 } });
              const y = interpolate(enterProgress, [0, 1], [20, 0]);
              const scale = interpolate(enterProgress, [0, 1], [0.85, 1]);
              const opacity = enterProgress;

              return (
                <div key={idx} style={{ transform: `translateY(${y}px) scale(${scale})`, opacity, transition: "none" }}>
                  <CardFace cardStr={card} accentGold={accentGold} />
                </div>
              );
            })}
          </div>
        </div>

        {/* PLAYER ZONE */}
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            padding: "20px 40px",
            borderRadius: 20,
            backgroundColor: "rgba(18, 18, 20, 0.8)",
            backdropFilter: "blur(20px)",
            border: `1px solid rgba(212,175,55,${0.1 + playerWinIntensity * 0.5})`,
            boxShadow: `0 12px 32px rgba(0,0,0,0.5), 0 0 ${playerWinIntensity * 40}px ${accentGold}60`,
            transition: "none",
          }}
        >
          <div style={{ display: "flex", alignItems: "center", gap: 32 }}>
            {/* Player Cards */}
            <div style={{ display: "flex", gap: 10 }}>
              {playerHand.map((card, idx) => {
                const enterProgress = spring({ frame: frame - 15 - idx * 5, fps, config: { damping: 14 } });
                const y = interpolate(enterProgress, [0, 1], [20, 0]);
                const opacity = enterProgress;

                return (
                  <div key={idx} style={{ transform: `translateY(${y}px)`, opacity, transition: "none" }}>
                    <CardFace cardStr={card} accentGold={accentGold} />
                  </div>
                );
              })}
            </div>

            {/* Info & Bets */}
            <div style={{ display: "flex", flexDirection: "column", justifyContent: "center" }}>
              <span style={{ fontFamily: montserratFamily, color: "#FFFFFF", fontSize: 18, fontWeight: 800, letterSpacing: 2, marginBottom: 12 }}>
                {playerName.toUpperCase()}
              </span>

              <div style={{ display: "flex", gap: 10 }}>
                {[
                  { label: "TRIPS", amount: betTrips, delay: 20 },
                  { label: "ANTE", amount: betAnte, delay: 25 },
                  { label: "BLIND", amount: betBlind, delay: 30 },
                  { label: "PLAY", amount: betPlay, delay: 35 },
                ].map((bet, idx) => {
                  const enter = spring({ frame: frame - bet.delay, fps, config: { damping: 14 } });
                  const y = interpolate(enter, [0, 1], [15, 0]);

                  return (
                    <div
                      key={idx}
                      style={{
                        display: "flex",
                        flexDirection: "column",
                        alignItems: "center",
                        opacity: enter,
                        transform: `translateY(${y}px)`,
                        transition: "none",
                        backgroundColor: "rgba(30, 30, 35, 0.6)",
                        border: `1px solid ${accentGold}40`,
                        borderRadius: 8,
                        padding: "6px 12px",
                        minWidth: 64,
                      }}
                    >
                      <span style={{ fontSize: 10, color: "#A0A0A0", letterSpacing: 1, fontFamily: montserratFamily, fontWeight: 700, marginBottom: 4 }}>
                        {bet.label}
                      </span>
                      <span style={{ fontSize: 14, color: "#FFF", fontWeight: 800, fontFamily: interFamily }}>
                        {bet.amount}
                      </span>
                    </div>
                  );
                })}
              </div>
            </div>
          </div>
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default CasinoOverlay;